mcp:tool-listener.mcp:parameters-schema:
{
  "type": "object",
  "properties": {
    "requestId": {
      "type": "string",
      "description": "Unique workflow request ID."
    },
    "approverSlackId": {
      "type": "string",
      "description": "Slack user ID of the approver."
    },
    "requestedBySlackId": {
      "type": "string",
      "description": "Slack user ID of the original requester."
    },
    "title": {
      "type": "string",
      "description": "Short approval request title."
    },
    "summary": {
      "type": "string",
      "description": "Summary of the request and its business justification."
    },
    "ticketIds": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1,
      "description": "Linear ticket identifiers requiring approval."
    },
    "ticketUrls": {
      "type": "array",
      "items": {
        "type": "string",
        "format": "uri"
      },
      "description": "Links to the generated Linear tickets."
    },
    "canvasUrl": {
      "type": "string",
      "format": "uri",
      "description": "Slack Canvas link containing request details."
    },
    "channelId": {
      "type": "string",
      "description": "Slack channel associated with the workflow."
    },
    "threadTs": {
      "type": "string",
      "description": "Original Slack thread timestamp."
    },
    "expiresInMinutes": {
      "type": "integer",
      "minimum": 1,
      "default": 60,
      "description": "Approval deadline in minutes."
    }
  },
  "required": [
    "requestId",
    "approverSlackId",
    "requestedBySlackId",
    "title",
    "summary",
    "ticketIds"
  ],
  "additionalProperties": false
}
